import{_ as t,a,o,a4 as r}from"./chunks/framework.-FZumj2l.js";const p=JSON.parse('{"title":"Inventory Sources","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/settings/inventory-sources/index.md","filePath":"api/graphql-api/admin/settings/inventory-sources/index.md","lastUpdated":1783327468000}'),n={name:"api/graphql-api/admin/settings/inventory-sources/index.md"};function d(s,e,i,c,l,u){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="inventory-sources" tabindex="-1">Inventory Sources <a class="header-anchor" href="#inventory-sources" aria-label="Permalink to &quot;Inventory Sources&quot;">​</a></h1><p>Inventory Sources are the physical or logical <strong>stock locations</strong> your products draw quantity from — a warehouse, a store backroom, a drop-ship hub. Each product carries a per-source quantity, sources are assigned to channels, and the source a shipment ships from is chosen at shipment time. This menu mirrors the admin <strong>Settings → Inventory Sources</strong> screen.</p><h2 id="what-an-inventory-source-represents" tabindex="-1">What an inventory source represents <a class="header-anchor" href="#what-an-inventory-source-represents" aria-label="Permalink to &quot;What an inventory source represents&quot;">​</a></h2><p>A source is a named place that holds stock. When you set a product&#39;s inventory, you enter a quantity <em>per source</em>; the storefront&#39;s available-to-sell quantity is the sum across the sources assigned to the active channel. When you create a shipment for an order, you pick which source the items ship from, and that source&#39;s quantity is decremented.</p><h2 id="field-meanings" tabindex="-1">Field meanings <a class="header-anchor" href="#field-meanings" aria-label="Permalink to &quot;Field meanings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>code</code></td><td>Unique machine identifier (letters, digits, dashes/underscores). Used internally and in imports; cannot collide with another source.</td></tr><tr><td><code>name</code></td><td>Human-readable label shown in the admin.</td></tr><tr><td><code>description</code></td><td>Optional free-text note.</td></tr><tr><td><code>contactName</code>, <code>contactEmail</code>, <code>contactNumber</code>, <code>contactFax</code></td><td>Contact details for the location&#39;s operator.</td></tr><tr><td><code>country</code>, <code>state</code>, <code>city</code>, <code>street</code>, <code>postcode</code></td><td>The source&#39;s physical address.</td></tr><tr><td><code>latitude</code>, <code>longitude</code></td><td>Optional geo-coordinates (used by distance-based source selection if configured).</td></tr><tr><td><code>priority</code></td><td>Ordering hint when several sources could fulfil an item — lower numbers are preferred first.</td></tr><tr><td><code>status</code></td><td><code>1</code> = active (available for stock + fulfilment), <code>0</code> = inactive.</td></tr><tr><td><code>createdAt</code>, <code>updatedAt</code></td><td>Timestamps. The seeded <code>default</code> source may report <code>null</code> for these.</td></tr></tbody></table><h2 id="creating-updating-deleting" tabindex="-1">Creating, updating &amp; deleting <a class="header-anchor" href="#creating-updating-deleting" aria-label="Permalink to &quot;Creating, updating &amp; deleting&quot;">​</a></h2><ul><li><strong>Create</strong> registers a new source. <code>code</code>, <code>name</code>, the contact fields and the address fields are required; <code>priority</code>, <code>status</code> and the geo-coordinates are optional.</li><li><strong>Update</strong> is a partial patch — send the <code>id</code> plus only the fields you want to change.</li><li><strong>Delete</strong> removes a single source; <strong>Mass Delete</strong> removes several by id in one call.</li></ul><h3 id="delete-guards" tabindex="-1">Delete guards <a class="header-anchor" href="#delete-guards" aria-label="Permalink to &quot;Delete guards&quot;">​</a></h3><p>A delete (single or mass) is <strong>refused</strong> when:</p><ul><li>it would remove the <strong>last remaining</strong> inventory source — a store must always have at least one; or</li><li>the source is still <strong>referenced by product inventories</strong> — some product holds stock at that source.</li></ul><p>A refused delete returns an error (equivalent to HTTP 422 on REST). Re-assign or zero out the product quantities at that source first, then retry.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/settings/inventory-sources/list.html">List inventory sources</a></td><td><code>adminSettingsInventorySources</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/settings/inventory-sources/detail.html">Get a single source</a></td><td><code>adminSettingsInventorySource(id:)</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/settings/inventory-sources/create.html">Create a source</a></td><td><code>createAdminSettingsInventorySource</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/settings/inventory-sources/update.html">Update a source</a></td><td><code>updateAdminSettingsInventorySource</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/settings/inventory-sources/delete.html">Delete a source</a></td><td><code>deleteAdminSettingsInventorySource</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/settings/inventory-sources/mass-delete.html">Mass delete sources</a></td><td><code>createAdminSettingsInventorySourceMassDelete</code> mutation</td></tr></tbody></table><p>Permissions: <code>settings.inventory_sources.create</code> / <code>.edit</code> / <code>.delete</code>.</p><p>All operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',16)]))}const m=t(n,[["render",d]]);export{p as __pageData,m as default};
